-- 竞赛专项种子题：填空题(type=3) + 解答题(type=4)
-- 覆盖 7 个竞赛分类：130算法面试 / 12 JavaScript / 111 Linux运维 / 80 机器学习 / 131 系统设计 / 70 Vue / 2 Python
-- 每分类 2 道填空 + 2 道解答，共 28 题；标题统一「【竞赛专项】」前缀便于幂等清理重跑
-- 填空题 answer 支持 | 分隔多候选（后端 normalizeText 归一化后比对）；解答题 answer 为判分要点关键词（AI 判分为主，关键词命中为降级）
SET NAMES utf8mb4;
USE `poti_question`;

DELETE FROM `question` WHERE `title` LIKE '【竞赛专项】%';

INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
-- ===================== 130 算法面试 =====================
(130, '【竞赛专项·算法】快速排序在平均情况下的时间复杂度是？（用大O表示法填写）', NULL, 3, 1, NULL, 'O(nlogn)|O(n log n)|O(n·log n)|nlogn', '快速排序平均每次划分将数组大致对半，共划分 O(log n) 层，每层比较 O(n)，故平均时间复杂度为 O(n log n)；最坏（已有序且取首元素为基准）退化为 O(n²)。', '算法;排序', 1),
(130, '【竞赛专项·算法】在一个长度为 n 的有序数组中执行二分查找，最坏情况下的时间复杂度是？（用大O表示法填写）', NULL, 3, 1, NULL, 'O(logn)|O(log n)|logn|log n', '二分查找每轮将搜索区间缩小一半，最坏情况需要缩到区间长度为 1，共 O(log n) 轮。前提是数组有序且支持随机访问。', '算法;查找', 1),
(130, '【竞赛专项·算法】请编写一个函数，反转一个单向链表并返回新的头节点。可以用任意语言，说明思路并给出代码。', NULL, 4, 2, NULL, 'prev|next|cur|current|指针|迭代|递归|反转', '核心思路（迭代法）：维护三个指针 prev、cur、next，每轮先暂存 cur.next，再将 cur.next 指向 prev 完成局部反转，然后三指针整体后移，直到 cur 为空，此时 prev 即新头节点。时间 O(n)、空间 O(1)；也可用递归实现，空间 O(n) 栈开销。', '算法;链表', 1),
(130, '【竞赛专项·算法】给定一个整数数组和目标值 target，找出数组中和为 target 的两个整数的下标（力扣第1题·两数之和）。请说明思路并编写代码。', NULL, 4, 2, NULL, '哈希|hash|map|字典|遍历|差值|target|补数|O(n)', '最优解法：用哈希表存「值→下标」，一次遍历，对每个数 x 查 target - x 是否已在表中，命中即返回两个下标；未命中则把 x 存入表。时间复杂度 O(n)、空间 O(n)。暴力双重循环 O(n²) 也可行但在竞赛中会超时。', '算法;哈希表', 1),
-- ===================== 12 JavaScript =====================
(12, '【竞赛专项·JS】表达式 typeof null 的返回值是？', NULL, 3, 1, NULL, 'object|"object"', '这是 JavaScript 的历史遗留 bug：typeof null 返回 "object"。由于早期实现中类型标签用低位表示，null 的指针全为 0 被归入 object 标签，该行为被保留至今。判断 null 应使用 value === null。', 'JavaScript;类型', 1),
(12, '【竞赛专项·JS】ES6 中声明存在暂时性死区、不会被变量提升的块级作用域变量的关键字是？（写一个即可）', NULL, 3, 1, NULL, 'let|const', 'let 和 const 声明的变量存在块级作用域与暂时性死区（TDZ），在声明语句执行前访问会抛 ReferenceError，且不会像 var 一样被提升并初始化为 undefined。const 额外要求声明时初始化且绑定不可重新赋值。', 'JavaScript;ES6', 1),
(12, '【竞赛专项·JS】请手写一个防抖函数 debounce：函数在停止触发 n 毫秒后才会真正执行，期间再次触发则重新计时。请给出代码并简述原理。', NULL, 4, 2, NULL, '闭包|timer|setTimeout|clearTimeout|延时|清除|定时', '核心原理：利用闭包保存定时器 id，每次触发时先 clearTimeout 取消上一次未执行的定时器，再重新 setTimeout 延迟执行；只有停止触发超过 wait 毫秒后定时器才会真正到期执行。注意返回的新函数需保留 this 与参数（可用 apply/箭头函数）。常用于搜索输入、窗口 resize 等高频场景。', 'JavaScript;手写题', 1),
(12, '【竞赛专项·JS】请手写一个深拷贝函数 deepClone，能正确拷贝嵌套对象与数组，并说明如何处理循环引用。', NULL, 4, 3, NULL, '递归|typeof|null|数组|Array|WeakMap|Map|循环引用|循环', '核心思路：递归遍历——对每个属性判断类型：基本类型直接返回；数组用 Array.isArray 判断后遍历拷贝；对象则新建空对象逐键递归。注意 typeof null === "object" 需先排除 null。循环引用处理：额外维护一个 Map/WeakMap 记录「原对象→拷贝对象」，递归前先查表，命中直接返回已有拷贝，避免无限递归栈溢出。', 'JavaScript;手写题', 1),
-- ===================== 111 Linux运维 =====================
(111, '【竞赛专项·Linux】在 Linux 中查看当前系统整体内存使用情况（总量/已用/空闲）的常用命令是？（不带参数的基础命令名）', NULL, 3, 1, NULL, 'free', 'free 命令以 KB/MB/GB 显示物理内存与交换分区的总量、已用、空闲及 buff/cache；常用 free -h 以人类可读单位输出。top/htop 也能看到内存但属于动态监控工具，/proc/meminfo 是底层数据来源。', 'Linux;命令', 1),
(111, '【竞赛专项·Linux】chmod 755 file 对应的九位字母权限形式是？（如 rwx------ 格式）', NULL, 3, 2, NULL, 'rwxr-xr-x', '755 按八进制拆为 7/5/5，即属主 rwx（读写执行）、属组 r-x（读执行）、其他人 r-x（读执行）。常用于目录和可执行脚本：目录需要 x 权限才能进入。', 'Linux;权限', 1),
(111, '【竞赛专项·Linux】线上某 Java 服务进程 CPU 占用接近 100%，请描述你的排查步骤并写出会用到的关键命令。', NULL, 4, 2, NULL, 'top|ps|pid|jstack|jstat|线程|tid|printf|十六进制', '标准排查链路：① top 找到 CPU 异常的进程 PID；② top -Hp PID（或 ps -Tp）定位该进程内 CPU 最高的线程 TID；③ printf "%x" TID 将线程号转十六进制；④ jstack PID | grep 0x十六进制 -A 30 输出该线程栈，定位到具体代码行；⑤ 若是 GC 问题先用 jstat -gcutil 看回收频率。也可用 arthas 等工具简化流程。', 'Linux;排查', 1),
(111, '【竞赛专项·Linux】请编写一条命令：删除 /var/log/app 目录下修改时间超过 30 天、以 .log 结尾的文件。', NULL, 4, 2, NULL, 'find|-mtime|+30|-name|*.log|-exec|rm|xargs', '标准答案：find /var/log/app -type f -name "*.log" -mtime +30 -exec rm -f {} \\;。-mtime +30 表示修改时间超过 30 天，-name 匹配文件名，-exec ... {} \\; 对每个结果执行删除；也可用管道 xargs：find ... | xargs rm -f。生产上建议先不加 -exec 用 ls {} 预览确认，防止误删。', 'Linux;命令', 1),
-- ===================== 80 机器学习 =====================
(80, '【竞赛专项·ML】线性回归中通过最小化残差平方和来估计参数的方法称为____法（填中文）。', NULL, 3, 1, NULL, '最小二乘|最小平方法|OLS', '最小二乘法（Least Squares / OLS）通过使所有样本的预测值与真实值之差的平方和最小来求解参数；对线性模型该问题有解析解（正规方程 θ=(XᵀX)⁻¹Xᵀy），也可用梯度下降迭代求解。', '机器学习;基础', 1),
(80, '【竞赛专项·ML】分类模型中精确率 Precision = TP / (TP + ____)。（填写缩写或中文术语）', NULL, 3, 2, NULL, 'fp|假阳性|假正例|误报', '精确率 = TP/(TP+FP)，衡量「预测为正的样本中真正为正的比例」；召回率 Recall = TP/(TP+FN)。精确率高说明误报少，召回率高说明漏报少，二者常用 F1 分数调和平均。', '机器学习;指标', 1),
(80, '【竞赛专项·ML】请解释梯度下降的基本原理：它如何一步步找到损失函数的最小值？请写出核心更新公式并说明学习率的作用。', NULL, 4, 2, NULL, '梯度|导数|负梯度|学习率|迭代|更新|收敛|极小|下降最快', '原理：损失函数在某点的梯度指向上升最快方向，故沿负梯度方向更新参数可最快下降。核心公式：θ = θ - η·∇L(θ)，其中 η 为学习率。学习率过大可能在极小值附近震荡甚至发散，过小则收敛缓慢。变体：批量/随机/小批量梯度下降；改进：Momentum、Adam 等自适应优化器。', '机器学习;优化', 1),
(80, '【竞赛专项·ML】什么是过拟合？请说明判断依据，并给出至少三种缓解过拟合的常用手段。', NULL, 4, 2, NULL, '正则化|L1|L2|Dropout|早停|交叉验证|数据增强|更多数据|简化模型|泛化', '过拟合：模型把训练数据的噪声也学进去了，训练误差很低但验证/测试误差高，泛化能力差。判断依据：训练集与验证集表现差距显著拉大。缓解手段：① L1/L2 正则化约束参数；② Dropout 随机失活神经元；③ 早停（验证集误差回升即停）；④ 数据增强或收集更多数据；⑤ 交叉验证选模型；⑥ 简化模型结构/减小树深度。', '机器学习;泛化', 1),
-- ===================== 131 系统设计 =====================
(131, '【竞赛专项·系统设计】CAP 定理中的三个特性分别是一致性（Consistency）、可用性（Availability）与____（填中文或英文）。', NULL, 3, 1, NULL, '分区容错性|分区容忍性|分区容错|partition tolerance', 'CAP 定理指出分布式系统无法同时完全满足一致性、可用性与分区容错性。网络分区（P）在分布式环境中不可避免，实际只能在 CP（如 ZooKeeper）与 AP（如 Eureka）之间权衡；BASE 理论是 AP 路线的工程延伸。', '系统设计;分布式', 1),
(131, '【竞赛专项·系统设计】Redis 中以 z 开头、支持按分数排序、常用于排行榜功能的数据结构是____。', NULL, 3, 1, NULL, 'zset|sorted set|有序集合|zset(有序集合)', 'ZSet（有序集合）每个成员关联一个 double 分数，按分数自动排序，支持 ZADD/ZRANGE/ZREVRANGE/ZINCRBY 等操作，底层为跳表+哈希表，增删查均为 O(log n)，是排行榜、延迟队列场景的标准选型。', '系统设计;Redis', 1),
(131, '【竞赛专项·系统设计】请设计一个短链接服务：将长 URL 转为短码，访问短链跳转到原地址。要求说明短码生成方案、存储设计与跳转流程，并考虑高并发与防重复。', NULL, 4, 3, NULL, '哈希|自增|id|base62|发号器|重定向|301|302|缓存|redis|布隆|冲突', '参考要点：① 短码生成：全局自增 ID + Base62 编码（发号器方案，无冲突、可预测长度）或对长 URL 哈希（MurmurHash/MD5）截取后查冲突；② 存储：MySQL 存「短码↔长URL」映射（短码唯一索引），Redis 缓存热点映射抗读流量；③ 跳转：302 临时重定向（可统计点击）或 301 永久（浏览器缓存省流量但难统计）；④ 防重复：同长链返回同短码可加布隆过滤器预判或唯一索引兜底；⑤ 高并发：读多写少，CDN/缓存 + 读写分离即可支撑。', '系统设计;高并发', 1),
(131, '【竞赛专项·系统设计】请设计一个支持瞬时 10 万 QPS 的电商秒杀系统：说明如何防止超卖、如何削峰，以及库存扣减的核心流程。', NULL, 4, 3, NULL, '限流|redis|预扣|lua|队列|mq|消息|库存|削峰|缓存|异步|下单|超卖|幂等', '参考要点：① 流量漏斗：前端按钮置灰/验证码 + 网关限流（令牌桶）挡住大部分请求；② 库存预扣：库存预热进 Redis，用 Lua 脚本原子完成「判断+扣减」防超卖，扣减成功才进入下单；③ 异步削峰：扣减成功后发 MQ，订单服务消费消息异步建单，数据库压力平摊；④ 兜底：DB 层乐观锁/库存判负 SQL（where stock >= n）防超卖；⑤ 幂等：请求带唯一令牌防重复下单；⑥ 失败补偿：支付超时回滚库存。', '系统设计;高并发', 1),
-- ===================== 70 Vue =====================
(70, '【竞赛专项·Vue】Vue 3 组合式 API 中，用于将基本类型值包装为响应式数据的函数是____。', NULL, 3, 1, NULL, 'ref', 'ref 用于包装基本类型（也可包装对象），通过 .value 访问与修改，模板中自动解包；对象/Map 等引用类型可用 reactive（无需 .value），但 reactive 不可整体替换、解构会丢失响应性，故推荐优先 ref。', 'Vue;组合式API', 1),
(70, '【竞赛专项·Vue】Vue 中父组件向子组件传值用 props，子组件向父组件传值应使用____触发自定义事件。', NULL, 3, 1, NULL, 'emit|$emit|emits|自定义事件', '子组件通过 this.$emit(事件名, 参数)（选项式）或 defineEmits 返回的 emit 函数（组合式）触发自定义事件，父组件以 @事件名="回调" 监听。跨层级/任意组件通信可改用 EventBus 或 Pinia/Vuex 状态管理。', 'Vue;组件通信', 1),
(70, '【竞赛专项·Vue】请详细说明 v-if 与 v-show 的区别，并分别给出适合的使用场景。', NULL, 4, 2, NULL, '编译|销毁|重建|dom|display|css|切换开销|频繁切换|初始|惰性', '区别：v-if 是真实的条件渲染——切换时组件经历创建/销毁（编译期惰性，初始为假时不渲染 DOM），切销开销大；v-show 仅编译为 display:none 的 CSS 切换，DOM 始终存在，初始渲染开销大。场景：条件很少变化用 v-if（如权限块）；频繁切换用 v-show（如 tab 内容）。注意 v-if 可与 v-else 连用，v-show 不支持 template 标签。', 'Vue;指令', 1),
(70, '【竞赛专项·Vue】请手写一个简易的事件总线（EventBus）：支持 on 监听、emit 触发、off 取消监听，并说明在 Vue 中何时用它替代 props 通信。', NULL, 4, 2, NULL, 'on|off|emit|事件|监听|回调|数组|缓存|map|订阅', '核心实现：用一个对象缓存事件与回调数组。on(event, cb) 将回调 push 进 event 对应数组；emit(event, ...args) 遍历该数组依次执行；off(event, cb) 从数组中移除指定回调（不传 cb 则清空全部）。注意 off 需用同一个函数引用，匿名函数无法取消。适用场景：无固定父子关系的跨组件通信（如兄弟组件、页面与弹层）；Vue 3 已移除 $on/$emit 总线，官方推荐 mitt 库或直接用 Pinia。', 'Vue;手写题', 1),
-- ===================== 2 Python =====================
(2, '【竞赛专项·Python】Python 中用于定义匿名函数的关键字是____。', NULL, 3, 1, NULL, 'lambda', 'lambda 参数: 表达式 创建匿名函数，只能写单个表达式且自动返回其值，常作为 sorted 的 key、map/filter 的回调。复杂逻辑应使用 def 定义具名函数保证可读性。', 'Python;基础', 1),
(2, '【竞赛专项·Python】Python 内置函数____可以将两个可迭代对象按下标一一配对，返回由元组组成的迭代器。', NULL, 3, 1, NULL, 'zip', 'zip(a, b) 将 a、b 对应位置元素组成 (a[i], b[i]) 元组，长度以较短者为准（Python 3.10+ 可用 strict=True 要求等长）；常与 dict(zip(keys, values)) 配合构造字典。', 'Python;内置函数', 1),
(2, '【竞赛专项·Python】请用生成器实现一个无限斐波那契数列（1, 1, 2, 3, 5, 8, ...），说明生成器相比直接返回列表的优势，并给出代码。', NULL, 4, 2, NULL, 'yield|生成器|无限|惰性|内存|迭代|while|循环', '实现：def fib(): a, b = 1, 1; while True: yield a; a, b = b, a+b。优势：生成器惰性求值、按需产出，不一次性构造整列，内存 O(1)，且天然支持无限序列（列表必须有限）；调用方用 next() 或 for + break 按需取值。这是「生成器适合流式/无限数据」的经典案例。', 'Python;生成器', 1),
(2, '【竞赛专项·Python】请编写函数统计一段英文文本中每个单词出现的次数，返回字典；说明你如何处理大小写，并给出代码。', NULL, 4, 1, NULL, 'dict|split|get|计数|字典|循环|Counter|lower|遍历', '基础实现：words = text.lower().split()；用 dict 累加——counts[w] = counts.get(w, 0) + 1，get 的默认值 0 避免 KeyError。更简洁可用 collections.Counter(words)，其 most_common(n) 还能直接取 TopN。大小写统一 lower() 归一化，避免 The/the 被算作两个词；复杂分词可用正则按字母序列提取后再统计。', 'Python;基础', 1);
